head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "popup2",
        type: "wframePopup", //browserPopup
        width: 900 + "px",
        height: 600 + "px",
        top: 100 + "px",
        left: 100 + "px",
        modal: false,
        useModalStack: true,
        className: "",
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true
    };
    $p.openPopup("wframe_isPopup_popupMain_531_(WSQ-4627)_sub_auto.xml", options);
};
scwin.trigger2_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "popup2",
        type: "browserPopup", //browserPopup
        width: 900 + "px",
        height: 600 + "px",
        top: 100 + "px",
        left: 100 + "px",
        modal: false,
        useModalStack: true,
        className: "",
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true
    };
    $p.openPopup("wframe_isPopup_popupMain_531_(WSQ-4627)_sub_auto.xml", options);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popup2_wframe_wframe1_textbox2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'true'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
